/**
 * game-boardroom.js - Boardroom Coup Defense Simulator (Chapter 8)
 * Simulates 2-2-1 Board dynamics, Independent Director lobbying,
 * and King (CEO retention) vs Rich (Permanent Board Steward) playbooks.
 */
window.VMGameBoardroom = (function() {
    function init() {
        const founderVotes = [1, 1]; // Founder 1, Founder 2
        const vcVotes = [-1, -1];    // VC 1, VC 2
        let independentVote = 0;     // 0 = swing/uncommitted, 1 = founder, -1 = VC
        let currentPlaybook = 'king'; // 'king' vs 'rich'

        const indepSeatBtn = document.getElementById('seat-independent');
        const votesDisplay = document.getElementById('board-votes-display');
        const verdictDisplay = document.getElementById('board-coup-verdict');
        const playbookKingBtn = document.getElementById('btn-playbook-king');
        const playbookRichBtn = document.getElementById('btn-playbook-rich');
        const playbookExpl = document.getElementById('board-playbook-explanation');

        if (!indepSeatBtn) return;

        function updateBoard() {
            // Count votes: > 0 supports founder CEO, < 0 votes to replace CEO
            let supportVotes = 2; // Founder seats always support founder
            let replaceVotes = 2; // VC seats vote for replacement

            if (independentVote === 1) {
                supportVotes += 1;
            } else if (independentVote === -1) {
                replaceVotes += 1;
            }

            if (votesDisplay) {
                votesDisplay.textContent = `${supportVotes} Support Founder vs ${replaceVotes} Support VC Replacement`;
            }

            if (indepSeatBtn) {
                indepSeatBtn.classList.remove('allied-founder', 'allied-vc', 'uncommitted');
                if (independentVote === 1) {
                    indepSeatBtn.classList.add('allied-founder');
                    indepSeatBtn.querySelector('.seat-status').textContent = 'Allied: Pro-Founder (3-2 Defends CEO)';
                } else if (independentVote === -1) {
                    indepSeatBtn.classList.add('allied-vc');
                    indepSeatBtn.querySelector('.seat-status').textContent = 'Allied: Pro-VC (3-2 Coup Ousts CEO)';
                } else {
                    indepSeatBtn.classList.add('uncommitted');
                    indepSeatBtn.querySelector('.seat-status').textContent = 'Swing Vote: Click to Lobby';
                }
            }

            if (verdictDisplay) {
                if (independentVote === 1) {
                    verdictDisplay.className = 'board-verdict success';
                    verdictDisplay.innerHTML = `
                        <strong>🛡️ CEO RETAINED (3-2 Vote)</strong>
                        <p>By securing the Independent Director through governance alignment and mutual consent, the founder retains executive authority.</p>
                    `;
                } else if (independentVote === -1) {
                    if (currentPlaybook === 'rich') {
                        verdictDisplay.className = 'board-verdict warning';
                        verdictDisplay.innerHTML = `
                            <strong>👑 STRATEGIC REPOSITIONING (Sandy Lerner Playbook)</strong>
                            <p>CEO transitions to Chairman & Chief Technologist with permanent voting seat. Founder retains governance veto and equity upside without operational firing liability.</p>
                        `;
                    } else {
                        verdictDisplay.className = 'board-verdict danger';
                        verdictDisplay.innerHTML = `
                            <strong>🚨 FOUNDER OUSTED (3-2 Coup)</strong>
                            <p>The VC coalition recruited the Independent Director (frequently an ex-VC or fellow portfolio member) and voted to replace the founder CEO with an external 'operator'.</p>
                        `;
                    }
                } else {
                    verdictDisplay.className = 'board-verdict neutral';
                    verdictDisplay.innerHTML = `
                        <strong>⚖️ DEADLOCKED (2-2 + 1 Swing)</strong>
                        <p>The fate of company control rests entirely in the hands of the single independent seat. Click the seat above to lobby them!</p>
                    `;
                }
            }
        }

        indepSeatBtn.addEventListener('click', () => {
            if (independentVote === 0) {
                independentVote = 1;
                if (window.VMAudio) window.VMAudio.playPreset('success');
            } else if (independentVote === 1) {
                independentVote = -1;
                if (window.VMAudio) window.VMAudio.playPreset('danger');
            } else {
                independentVote = 0;
                if (window.VMAudio) window.VMAudio.playPreset('click');
            }
            updateBoard();
        });

        if (playbookKingBtn && playbookRichBtn) {
            playbookKingBtn.addEventListener('click', () => {
                currentPlaybook = 'king';
                playbookKingBtn.classList.add('active');
                playbookRichBtn.classList.remove('active');
                if (playbookExpl) {
                    playbookExpl.innerHTML = `
                        <strong>King Strategy:</strong> You prioritize retaining the CEO seat at all costs. If you lose the 3-2 board vote, you are terminated from operations and your unvested shares may be forfeited under adverse departure clauses.
                    `;
                }
                if (window.VMAudio) window.VMAudio.playPreset('click');
                updateBoard();
            });

            playbookRichBtn.addEventListener('click', () => {
                currentPlaybook = 'rich';
                playbookRichBtn.classList.add('active');
                playbookKingBtn.classList.remove('active');
                if (playbookExpl) {
                    playbookExpl.innerHTML = `
                        <strong>Rich Strategy (Wiener / Cisco Playbook):</strong> You negotiate an irrevocable Founder Board Seat and transition willingly to Executive Chairman/Chief Architect when growth demands enterprise scale. You cannot be locked out of company destiny.
                    `;
                }
                if (window.VMAudio) window.VMAudio.playPreset('success');
                updateBoard();
            });
        }

        updateBoard();
    }

    return { init };
})();


/* --- source/games/game-safes.js --- */
/**
 * game-safes.js - SAFE Stacker & The 3-Year QSBS Clock (Chapters 12 & 13)
 * Demonstrates valuation cap dilution stacks, discount triggers, and
 * the Section 1202 holding period tax shielding benefits of SAFEs vs Notes.
 */
window.VMGameSafes = (function() {
    function init() {
        const safe1Amount = document.getElementById('safe1-amount');
        const safe1Cap = document.getElementById('safe1-cap');
        const safe2Amount = document.getElementById('safe2-amount');
        const safe2Cap = document.getElementById('safe2-cap');
        const seriesAPre = document.getElementById('safe-input-pricedval');
        const seriesARaised = document.getElementById('safe-input-seriesaraise');
        const instrumentSelect = document.getElementById('safe-instrument-type');

        if (!safe1Amount) return;

        function update() {
            const s1Amt = parseFloat(safe1Amount.value) || 500000;
            const s1Cap = parseFloat(safe1Cap.value) || 5000000;
            const s2Amt = parseFloat(safe2Amount.value) || 1000000;
            const s2Cap = parseFloat(safe2Cap.value) || 10000000;
            const preMoney = parseFloat(seriesAPre.value) || 20000000;
            const newRaise = parseFloat(seriesARaised.value) || 5000000;
            const instrument = instrumentSelect ? instrumentSelect.value : 'safe'; // 'safe' vs 'note'

            // Base shares before SAFEs (founder common = 10M shares)
            const founderShares = 10000000;
            const seriesASharePrice = preMoney / founderShares;

            // Safe 1 effective price
            const s1Price = Math.min(seriesASharePrice, s1Cap / founderShares);
            const s1Shares = s1Amt / s1Price;

            // Safe 2 effective price
            const s2Price = Math.min(seriesASharePrice, s2Cap / founderShares);
            const s2Shares = s2Amt / s2Price;

            // Series A new investor shares
            const seriesAShares = newRaise / seriesASharePrice;

            const totalPostShares = founderShares + s1Shares + s2Shares + seriesAShares;

            const founderDilutedPct = (founderShares / totalPostShares) * 100;
            const safe1Pct = (s1Shares / totalPostShares) * 100;
            const safe2Pct = (s2Shares / totalPostShares) * 100;
            const seriesAPct = (seriesAShares / totalPostShares) * 100;

            // QSBS Section 1202 Clock Math (100% federal capital gains exclusion on up to $10M)
            let qsbsDaysAccrued = 0;
            let qsbsEligible = false;
            let taxSavingsPotential = 0;

            if (instrument === 'safe' || instrument === 'vmsafe') {
                // SAFE qualifies as equity from Day 1 of investment
                qsbsDaysAccrued = 1095; // 3 years holding period satisfied
                qsbsEligible = true;
                taxSavingsPotential = Math.min(10000000, newRaise * 2) * 0.20; // 20% federal capital gains saved
            } else {
                // Convertible debt is debt until converted; clock started 0 days ago at Series A
                qsbsDaysAccrued = 0;
                qsbsEligible = false;
                taxSavingsPotential = 0;
            }

            // Update DOM displays
            document.getElementById('safe-disp-s1-amt').textContent = '$' + (s1Amt / 1e3).toFixed(0) + 'K';
            document.getElementById('safe-disp-s1-cap').textContent = '$' + (s1Cap / 1e6).toFixed(1) + 'M';
            document.getElementById('safe-disp-s2-amt').textContent = '$' + (s2Amt / 1e6).toFixed(1) + 'M';
            document.getElementById('safe-disp-s2-cap').textContent = '$' + (s2Cap / 1e6).toFixed(1) + 'M';
            document.getElementById('safe-disp-pricedval').textContent = '$' + (preMoney / 1e6).toFixed(1) + 'M';
            document.getElementById('safe-disp-seriesaraise').textContent = '$' + (newRaise / 1e6).toFixed(1) + 'M';

            document.getElementById('safe-disp-founder-pct').textContent = founderDilutedPct.toFixed(1) + '%';
            document.getElementById('safe-disp-s1-pct').textContent = safe1Pct.toFixed(1) + '%';
            document.getElementById('safe-disp-s2-pct').textContent = safe2Pct.toFixed(1) + '%';
            document.getElementById('safe-disp-seriesa-pct').textContent = seriesAPct.toFixed(1) + '%';

            const qsbsClockEl = document.getElementById('qsbs-clock-display');
            if (qsbsClockEl) {
                if (qsbsEligible) {
                    qsbsClockEl.textContent = '3 Years (Qualified: 100% Fed Tax Exclusion Under §1202)';
                    qsbsClockEl.style.color = '#10b981';
                } else {
                    qsbsClockEl.textContent = '0 Days (Debt Clock Frozen Until Conversion)';
                    qsbsClockEl.style.color = '#ef4444';
                }
            }

            const qsbsSavingsEl = document.getElementById('qsbs-tax-savings');
            if (qsbsSavingsEl) {
                qsbsSavingsEl.textContent = '+$' + Math.round(taxSavingsPotential).toLocaleString();
            }
        }

        [safe1Amount, safe1Cap, safe2Amount, safe2Cap, seriesAPre, seriesARaised].forEach(inp => {
            inp.addEventListener('input', () => {
                update();
                if (window.VMAudio) window.VMAudio.playTone(400, 'sine', 0.05, 0.08);
            });
        });

        if (instrumentSelect) {
            instrumentSelect.addEventListener('change', () => {
                update();
                if (window.VMAudio) window.VMAudio.playPreset('click');
            });
        }

        update();
    }

    return { init };
})();


/* --- source/games/game-vesting.js --- */
/**
 * game-vesting.js - Reverse Vesting & The 83(b) Tax Escape (Chapters 10, 15 & 16)
 * Simulates restricted stock with reverse vesting vs standard unexercised options,
 * the 30-day strict Section 83(b) election, and phantom income prevention.
 */
window.VMGameVesting = (function() {
    function init() {
        const grantSharesInput = document.getElementById('rv-input-grantshares');
        const parValInput = document.getElementById('rv-input-parval');
        const exitPriceInput = document.getElementById('rv-input-exitprice');
        const check83b = document.getElementById('rv-check-83b');
        const departureMonthInput = document.getElementById('rv-input-departuremonth');
        const vestingTypeSelect = document.getElementById('rv-select-type');

        if (!grantSharesInput) return;

        function update() {
            const grantShares = parseFloat(grantSharesInput.value) || 2000000;
            const parValue = parseFloat(parValInput.value) || 0.001;
            const exitSharePrice = parseFloat(exitPriceInput.value) || 15.0;
            const has83b = check83b ? check83b.checked : true;
            const departureMonth = parseInt(departureMonthInput ? departureMonthInput.value : 48) || 48;
            const vestingType = vestingTypeSelect ? vestingTypeSelect.value : 'restricted'; // 'restricted' vs 'options'

            // Standard 4-year monthly vesting with 1-year (12-month) cliff
            let vestedFraction = 0;
            if (departureMonth < 12) {
                vestedFraction = 0;
            } else if (departureMonth >= 48) {
                vestedFraction = 1.0;
            } else {
                vestedFraction = departureMonth / 48;
            }

            const vestedShares = grantShares * vestedFraction;
            const grossProceeds = vestedShares * exitSharePrice;
            const initialPurchaseCost = grantShares * parValue;

            let taxOwed = 0;
            let netTakeHome = 0;
            let taxExplanation = '';

            if (vestingType === 'restricted') {
                if (has83b) {
                    // Filed within 30 days: tax paid upfront on Day 1 on initial value (almost $0)
                    // At exit, all profit taxed as Long-Term Capital Gains (20%) or $0 if QSBS holds!
                    const capitalGain = Math.max(0, grossProceeds - (vestedShares * parValue));
                    taxOwed = capitalGain * 0.20;
                    netTakeHome = grossProceeds - taxOwed - initialPurchaseCost;
                    taxExplanation = 'Section 83(b) Election Filed on Day 1: Growth taxed at 20% Long-Term Capital Gains rate (or 0% under QSBS §1202). No phantom ordinary income!';
                } else {
                    // Missed 83(b): As shares vest each year at higher valuations, taxed as ORDINARY INCOME (up to 37%)!
                    const avgVestValuationPerShare = exitSharePrice * 0.6; // Average fair market value at vesting
                    const ordinaryTax = (vestedShares * avgVestValuationPerShare) * 0.37;
                    const capitalGainsTax = Math.max(0, grossProceeds - (vestedShares * avgVestValuationPerShare)) * 0.20;
                    taxOwed = ordinaryTax + capitalGainsTax;
                    netTakeHome = grossProceeds - taxOwed - initialPurchaseCost;
                    taxExplanation = 'WARNING: Missed 30-Day 83(b) Election! The IRS taxed unvested appreciation as 37% Ordinary Income at each vesting milestone. Devastating cash crunch.';
                }
            } else {
                // Stock Options: 90-day post-termination exercise window
                // If founder leaves before liquidity, must pay cash strike price + AMT tax, or forfeit everything!
                if (departureMonth < 48) {
                    taxOwed = grossProceeds * 0.45; // Exercise penalty + AMT + short term tax
                    netTakeHome = Math.max(0, grossProceeds - taxOwed - (vestedShares * 2.0)); // Assume $2 strike
                    taxExplanation = 'Option Golden Handcuffs: Left before exit. 90-day post-termination window required $4M+ cash to exercise and pay AMT, forcing painful forfeiture.';
                } else {
                    taxOwed = grossProceeds * 0.28;
                    netTakeHome = grossProceeds - taxOwed;
                    taxExplanation = 'Exercised stock options at exit. Higher tax than restricted stock with 83(b), and QSBS clock started years later.';
                }
            }

            // Update DOM displays
            document.getElementById('rv-disp-grantshares').textContent = grantShares.toLocaleString();
            document.getElementById('rv-disp-vestedshares').textContent = Math.round(vestedShares).toLocaleString();
            document.getElementById('rv-disp-gross').textContent = '$' + Math.round(grossProceeds).toLocaleString();
            document.getElementById('rv-disp-tax').textContent = '-$' + Math.round(taxOwed).toLocaleString();
            
            const netEl = document.getElementById('rv-disp-net-takehome');
            if (netEl) {
                netEl.textContent = '$' + Math.round(netTakeHome).toLocaleString();
                if (has83b && vestingType === 'restricted') {
                    netEl.style.color = '#10b981';
                } else {
                    netEl.style.color = '#f59e0b';
                }
            }

            const explEl = document.getElementById('rv-disp-tax-explanation');
            if (explEl) {
                explEl.textContent = taxExplanation;
            }
        }

        [grantSharesInput, parValInput, exitPriceInput, departureMonthInput].forEach(inp => {
            if (inp) {
                inp.addEventListener('input', () => {
                    update();
                    if (window.VMAudio) window.VMAudio.playTone(480, 'sine', 0.05, 0.06);
                });
            }
        });

        if (check83b) {
            check83b.addEventListener('change', () => {
                update();
                if (window.VMAudio) {
                    if (check83b.checked) {
                        window.VMAudio.playPreset('success');
                    } else {
                        window.VMAudio.playPreset('danger');
                    }
                }
            });
        }

        if (vestingTypeSelect) {
            vestingTypeSelect.addEventListener('change', () => {
                update();
                if (window.VMAudio) window.VMAudio.playPreset('click');
            });
        }

        update();
    }

    return { init };
})();


/* --- source/main.js --- */
/**
 * main.js - Master Orchestrator for Venture Mechanics
 * Initializes all sub-game modules, official Venture Mechanics ads, and audio hooks.
 */
document.addEventListener('DOMContentLoaded', () => {
    // 1. Initialize core audio
    if (window.VMAudio) {
        // Unlock audio on first user touch/click
        const unlockAudio = () => {
            window.VMAudio.playTone(0, 'sine', 0.001);
            window.removeEventListener('click', unlockAudio);
            window.removeEventListener('touchstart', unlockAudio);
        };
        window.addEventListener('click', unlockAudio);
        window.addEventListener('touchstart', unlockAudio);
    }

    // 2. Initialize Venture Mechanics banners & book CTAs
    if (window.VMBanner && window.VMBanner.init) {
        window.VMBanner.init();
    }
    if (window.VMBookCTA && window.VMBookCTA.init) {
        window.VMBookCTA.init();
    }

    // 3. Initialize Top Navigation
    if (window.VMNavigation && window.VMNavigation.init) {
        window.VMNavigation.init();
    }

    // 4. Initialize Sub-Games
    if (window.VMGameLLC && window.VMGameLLC.init) {
        window.VMGameLLC.init();
    }
    if (window.VMGameRatchet && window.VMGameRatchet.init) {
        window.VMGameRatchet.init();
    }
    if (window.VMGameBoardroom && window.VMGameBoardroom.init) {
        window.VMGameBoardroom.init();
    }
    if (window.VMGameSafes && window.VMGameSafes.init) {
        window.VMGameSafes.init();
    }
    if (window.VMGameVesting && window.VMGameVesting.init) {
        window.VMGameVesting.init();
    }

    console.log('Venture Mechanics Suite initialized with 6 sub-games and VentureMechanics.com integration.');
});
